#!/usr/bin/env python3
"""
cli.py — Unified Subcommand Runner for Sovereign MoE PCIe Experiments
Provides a single entry point to run any of the 8 experiments or the full suite,
with optional JSON output and help flag.
"""

import argparse
import json
import os
import sys
import subprocess
from typing import Dict, Any

EXPERIMENTS = {
    "1": "exp1_link_bandwidth.py",
    "2": "exp2_dispatch_tax.py",
    "3": "exp3_triton_zerocopy_tile.py",
    "4": "exp4_double_buffered_dma.py",
    "5": "exp5_ptx_cache_surgery.py",
    "6": "exp6_memory_substrates.py",
    "7": "exp7_tiered_moe_simulation.py",
    "8": None,  # server.ts is not a Python script; we'll handle separately
}

def run_experiment(exp_id: str, json_out: bool = False) -> Dict[str, Any]:
    """Run a single experiment and return its parsed JSON output."""
    script = EXPERIMENTS.get(exp_id)
    if script is None:
        if exp_id == "8":
            # For experiment 8, we need to start the server and query it.
            # For simplicity in this CLI, we'll just return a placeholder.
            # In reality, we'd start the server in background, query, then stop.
            return {
                "experiment": "exp8_server_dashboard",
                "note": "Experiment 8 is a Bun HTTP/WebSocket server. Use `bun run /home/toxic/estate/tools/pcie-moe/server.ts` to start.",
                "status": "placeholder"
            }
        else:
            raise ValueError(f"Unknown experiment ID: {exp_id}")

    script_path = os.path.join(os.path.dirname(__file__), script)
    cmd = [sys.executable, script_path]
    if json_out:
        cmd.append("--json")

    # Run the script and capture output
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    if result.returncode != 0:
        raise RuntimeError(f"Experiment {exp_id} failed:\n{result.stderr}")

    # Try to parse JSON from stdout
    try:
        data = json.loads(result.stdout.strip())
        return data
    except json.JSONDecodeError:
        # If not JSON, wrap in a text result
        return {
            "experiment": f"exp{exp_id}",
            "raw_output": result.stdout.strip(),
            "note": "Output was not JSON; raw output provided."
        }

def run_all(json_out: bool = False) -> Dict[str, Any]:
    """Run all experiments 1-7 and optionally 8 (server status check)."""
    results = {}
    for exp_id in ["1", "2", "3", "4", "5", "6", "7"]:
        try:
            results[f"exp{exp_id}"] = run_experiment(exp_id, json_out=json_out)
        except Exception as e:
            results[f"exp{exp_id}"] = {"error": str(e)}
    # For exp8, we can do a simple health check if server is running, or note it's a server.
    results["exp8"] = {
        "experiment": "exp8_server_dashboard",
        "note": "Experiment 8 is a Bun HTTP/WebSocket server on port 25219. To test, start the server and curl http://localhost:25219/api/status",
        "status": "placeholder"
    }
    return results

def main():
    parser = argparse.ArgumentParser(
        description="Unified runner for Sovereign MoE PCIe Experiments (1-8)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  python cli.py 1              # Run experiment 1 with human-readable output
  python cli.py 1 --json       # Run experiment 1 and output JSON
  python cli.py all            # Run all experiments (1-7) and show summary
  python cli.py all --json     # Run all experiments and output combined JSON
  python cli.py 8              # Show info about experiment 8 (the server)
        """
    )
    parser.add_argument(
        "target",
        choices=["1", "2", "3", "4", "5", "6", "7", "8", "all"],
        help="Experiment ID to run, or 'all' for experiments 1-7, or '8' for the server info."
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Output results as JSON (machine-readable)."
    )
    parser.add_argument(
        "--out",
        type=str,
        default="",
        help="If set, write JSON output to this file path (implies --json)."
    )
    args = parser.parse_args()

    if args.target == "all":
        payload = run_all(json_out=args.json)
    else:
        payload = run_experiment(args.target, json_out=args.json)

    # Output
    if args.json or args.out:
        output_str = json.dumps(payload, indent=2)
        if args.out:
            os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
            with open(args.out, "w") as f:
                f.write(output_str)
            print(f"Results written to {args.out}")
        if not args.out:
            print(output_str)
    else:
        # Human-readable summary
        if args.target == "all":
            print("=" * 80)
            print("SOVEREIGN MOE PCIE EXPERIMENTS — SUMMARY")
            print("=" * 80)
            for exp_id in ["1", "2", "3", "4", "5", "6", "7", "8"]:
                res = payload.get(f"exp{exp_id}", {"error": "not run"})
                if "error" in res:
                    print(f"Experiment {exp_id}: ERROR — {res['error']}")
                else:
                    # Try to extract a nice summary line
                    exp_name = res.get("experiment", f"exp{exp_id}")
                    if exp_id == "8":
                        print(f"Experiment {exp_id}: {res.get('note', 'Server dashboard')}")
                    else:
                        # Look for pass criteria or key metric
                        passed = res.get("pass_criteria_met", None)
                        if passed is not None:
                            status = "PASS" if passed else "FAIL"
                            print(f"Experiment {exp_id}: {exp_name} — {status}")
                        else:
                            print(f"Experiment {exp_id}: {exp_name}")
        else:
            # Single experiment human-readable
            if isinstance(payload, dict) and "error" in payload:
                print(f"ERROR: {payload['error']}")
            else:
                # Just pretty print the dict
                print(json.dumps(payload, indent=2))

if __name__ == "__main__":
    main()

/**
 * server.ts — Sovereign Telemetry Service & Dashboard for PCIe MoE Experiments
 * Bun HTTP + WebSocket daemon on port 25219 (SSOT configured in ports.env)
 * Provides:
 *   - GET /api/status: Real-time PCIe link, VRAM, temperature, power.
 *   - POST /api/run/:exp_id: Runs experiment 1-7 and returns JSON.
 *   - GET /: Simple interactive console with placeholders for live SVG.
 */

import { stdout } from "bun";

const PORT = process.env.PCIE_MOE_PORT ?? 25219;

// Helper to run a Python experiment and return parsed JSON or text
async function runPythonExperiment(expId: number): Promise<any> {
  const scriptMap: Record<number, string> = {
    1: "exp1_link_bandwidth.py",
    2: "exp2_dispatch_tax.py",
    3: "exp3_triton_zerocopy_tile.py",
    4: "exp4_double_buffered_dma.py",
    5: "exp5_ptx_cache_surgery.py",
    6: "exp6_memory_substrates.py",
    7: "exp7_tiered_moe_simulation.py",
  };
  const script = scriptMap[expId];
  if (!script) {
    throw new Error(`Invalid experiment ID: ${expId}`);
  }
